// Make sure src/capture.json exists before the composition is bundled.
//
// capture.json is generated by the capture scripts and git-ignored: it records
// the real tenant URLs and the size of each take. A fresh clone has only
// capture.example.json, so the first build copies that; the scenes then show
// "missing take" captions until footage is recorded, which is the honest state.
//
//   node scripts/ensure-capture.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const src = path.resolve(here, '..', 'src');
const target = path.join(src, 'capture.json');
const example = path.join(src, 'capture.example.json');

if (fs.existsSync(target)) {
  process.exit(0);
}

if (!fs.existsSync(example)) {
  console.error('missing src/capture.example.json and src/capture.json');
  process.exit(1);
}

fs.copyFileSync(example, target);
console.log('created src/capture.json from capture.example.json — run the capture scripts to fill it with real takes');
